import ctypes, hashlib, json, os, subprocess, sys, time
from datetime import datetime, timezone
from pathlib import Path
sys.path.insert(0,str(Path.cwd()))
from benchmark.harness import evaluate as h
import httpx
from app.services.model_gateway.ollama_runtime import OllamaRuntime
OUT=Path('benchmark/reports/phase10_2_runtime_probe.json')
basepath=Path('benchmark/results/phase10_1_repair_results.jsonl')
base={r['case_id']:r for r in map(json.loads,basepath.read_text(encoding='utf-8').splitlines())}
config=h.settings.model_copy(update={'model_runtime':'ollama','model_name':'qwen3.5:9b','model_base_url':'http://127.0.0.1:11434','model_temperature':0,'model_seed':42,'model_context_window':16384,'model_max_retries':0})
client=httpx.Client(base_url='http://127.0.0.1:11434',trust_env=False,timeout=900,follow_redirects=False)
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def unbiased():
 v=ctypes.c_ulonglong(); assert ctypes.windll.kernel32.QueryUnbiasedInterruptTime(ctypes.byref(v)); return v.value/1e7
if OUT.exists(): data=json.loads(OUT.read_text())
else:
 show=client.post('/api/show',json={'model':'qwen3.5:9b'}); show.raise_for_status(); show=show.json()
 data={'started_utc':datetime.now(timezone.utc).isoformat(),'baseline_sha256':sha(basepath),'harness_sha256':sha('benchmark/harness/evaluate.py'),'ollama_version':client.get('/api/version').json(),'model_details':show.get('details'),'model_capabilities':show.get('capabilities'),'modelfile_header':show.get('modelfile','').split('LICENSE')[0],'model_parameters':show.get('parameters'),'model_inventory':client.get('/api/tags').json(),'measurements':[]}
awake=ctypes.windll.kernel32.SetThreadExecutionState(0x80000001)
assert awake, 'Unable to request process-scoped idle-sleep prevention'
try:
 for mode in sys.argv[1:]:
  for case_id in ('JSON-003','OBS-005'):
   assert not any(r['case_id']==case_id and r['mode']==mode for r in data['measurements']), 'Never repeat an existing measurement'
   assert len(data['measurements'])<6
   row=base[case_id]; saved=row['requests'][1]['messages']; context=json.loads(saved[1]['content']); final=json.loads(saved[-1]['content'])
   assert set(context)=={'request','context','task','available_routes','available_tools','response_schema'}
   if mode in ('A','C'):
    messages=[h.ChatMessage.model_validate(m) for m in saved]
   else:
    body={'request':context['request'],'context':context['context'],**final}
    messages=[h.ChatMessage.model_validate(saved[0]),h.ChatMessage(role='user',content=json.dumps(body,ensure_ascii=False))]
   record={'case_id':case_id,'mode':mode,'saved_plan':json.loads(saved[2]['content']),'evidence_returned':final['untrusted_tool_results'],'answer_schema':final['response_schema'],'message_roles':[m.role for m in messages],'started_utc':datetime.now(timezone.utc).isoformat(),'awake_request_succeeded':bool(awake)}
   def send(request):
    record['endpoint']=str(request.url); record['wire_request']=json.loads(request.content)
    response=client.request(request.method,str(request.url),content=request.content,headers={'Content-Type':'application/json'})
    record['http_status']=response.status_code
    try: record['native_response']=response.json()
    except Exception: record['native_response_text']=response.text
    return response
   runtime=OllamaRuntime(config,transport=httpx.MockTransport(send)); gateway=h.ModelGateway(config,runtime=runtime)
   start=time.perf_counter(); wall=time.time(); awake_start=unbiased()
   print('Running',case_id,mode,flush=True)
   try:
    if mode=='C':
     # Direct native chat, same A request; only add schema-constrained decoding.
     payload={**next(r['wire_request'] for r in data['measurements'] if r['case_id']==case_id and r['mode']=='A'),'format':final['response_schema']}
     response=send(httpx.Request('POST','http://127.0.0.1:11434/api/chat',json=payload)); response.raise_for_status()
     result=runtime._map_chat_response(response.json(),model='qwen3.5:9b')
    else:
     result=gateway.generate_text(messages=messages,temperature=0,think=False,max_output_tokens=1536,timeout_seconds=900)
    record['generation_result']=result.model_dump(mode='json')
    try:
     parsed=h.strict_json(result.text); record['parsed_response']=parsed
     record['planning_json_returned']=isinstance(parsed,dict) and set(parsed)=={'route','tools'}
     record['exact_previous_plan_echo']=parsed==record['saved_plan']
     h.parse(result.text,h.SCHEMAS['S3']); record['schema_valid']=True
    except Exception as error:
     record['schema_valid']=False; record['parse_error']=str(error)
    supplied=list({r['evidence_id']:r for v in final['untrusted_tool_results'].values() for r in v}.values())
    record['critical_findings']=h.critical_findings(record.get('parsed_response',result.text),supplied)
    if result.truncated: record['runtime_error']='Truncated output'
    if (result.timings.total_ms or 0)>900000: record['runtime_error']='Deadline exceeded in runtime timing'
   except Exception as error: record['runtime_error']=type(error).__name__+': '+str(error)
   record['latency_seconds']=time.perf_counter()-start
   record['ended_utc']=datetime.now(timezone.utc).isoformat()
   record['wall_minus_awake_seconds']=(time.time()-wall)-(unbiased()-awake_start)
   record['measurement_valid']=record['wall_minus_awake_seconds']<2 and 'runtime_error' not in record and record['latency_seconds']<=900
   data['measurements'].append(record)
   OUT.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
   print(case_id,mode,'schema',record.get('schema_valid'),'plan',record.get('planning_json_returned'),'seconds',round(record['latency_seconds'],2),'valid',record['measurement_valid'],flush=True)
finally:
 ctypes.windll.kernel32.SetThreadExecutionState(0x80000000)
 client.close()
